  "regions": [
    {
      "id": "r2",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "एकेनापि हि शूरेण पादाक्रान्तं महीतलम् ।",
          "end": "line"
        },
        {
          "n": 2,
          "text": "क्रियते भास्करेणेव स्फारस्फुरिततेजसा ॥ १०८ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "वह्निस्तस्य जलायते जलनिधिः कुल्यायते तत्क्षणा-",
          "end": "hyphen"
        },
        {
          "n": 2,
          "text": "न्मेरुः स्वल्पशिलायते मृगपतिः सद्यः कुरङ्गायते ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "व्यालो माल्यगुणायते विषरसः पीयूषवर्षायते",
          "end": "line"
        },
        {
          "n": 4,
          "text": "यस्याङ्गेखिललोकवल्लभतमं शीलं समुन्मीलति ॥ १०९ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "लज्जागुणौघजननीं जननीमिव स्वा-",
          "end": "hyphen"
        },
        {
          "n": 2,
          "text": "मत्यन्तशुद्धहृदयामनुवर्तमानाम् ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "",
          "end": "space"
        },
        {
          "n": 4,
          "text": "तेजस्विनः सुखमसूनपि संत्यजन्ति",
          "end": "line"
        },
        {
          "n": 5,
          "text": "सत्यव्रतव्यसनिनो न पुनः प्रतिज्ञाम् ॥ ११० ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "heading",
      "lines": [
        {
          "n": 1,
          "text": "MISCELLANEOUS.",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "अग्राह्यं हृदयं यथैव वदनं यद्दर्पणान्तर्गतं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "भावः पर्वतसूक्ष्ममार्गविषमः स्त्रीणां न विज्ञायते ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "चित्तं पुष्करपत्रतोयतरलं विद्वद्भिराशंसितं",
          "end": "line"
        },
        {
          "n": 4,
          "text": "नारी नाम विषाङ्कुरैरिव लता दोषैः समं वर्द्धिता ॥ १ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r7",
      "type": "apparatus_entry",
      "lines": [
        {
          "n": 1,
          "text": "CVIII. (a) °पि हि; °पीह T. पा°; प° T. P. मही; क्षमा K. (b) °रेणे°;",
          "end": "space"
        },
