      "type": "apparatus_entry",
      "lines": [
        {
          "n": 1,
          "text": "CX. (a) °ज्जा°; °ज्जाम्. P. R. Be.n. जननीमिव स्वाम्; इव वर्तमानाम्.",
          "end": "space"
        },
